@push('scripts')
    <script>
        $(document).ready(function(){

            $("#timepicker2").timepicker({
                showMeridian: !1,
                icons: { up: "mdi mdi-chevron-up", down: "mdi mdi-chevron-down" },
                appendWidgetTo: "#timepicker-input-group2",
            });
        
            $(".select2").select2();

            $(".select2-ajax").select2({
                ajax: {
                    url: "https://api.github.com/search/repositories",
                    dataType: "json",
                    delay: 250,
                    data: function (e) {
                        return { q: e.term, page: e.page };
                    },
                    processResults: function (e, t) {
                        return (
                        (t.page = t.page || 1),
                        {
                            results: e.items,
                            pagination: { more: 30 * t.page < e.total_count },
                        }
                        );
                    },
                    cache: !0,
                },
                placeholder: "Search for a repository",
                minimumInputLength: 1,
                templateResult: function (e) {
                    if (e.loading) return e.text;
                    var t = $(
                        "<div class='select2-result-repository clearfix'><div class='select2-result-repository__avatar'><img src='" +
                        e.owner.avatar_url +
                        "' /></div><div class='select2-result-repository__meta'><div class='select2-result-repository__title'></div><div class='select2-result-repository__description'></div><div class='select2-result-repository__statistics'><div class='select2-result-repository__forks'><i class='fa fa-flash'></i> </div><div class='select2-result-repository__stargazers'><i class='fa fa-star'></i> </div><div class='select2-result-repository__watchers'><i class='fa fa-eye'></i> </div></div></div></div>",
                    );
                    return (
                        t.find(".select2-result-repository__title")
                            .text(e.full_name),
                        t.find(".select2-result-repository__description")
                            .text(e.description),
                        t.find(".select2-result-repository__forks")
                            .append(e.forks_count + " Forks"),
                        t.find(".select2-result-repository__stargazers")
                            .append(e.stargazers_count + " Stars"),
                        t.find(".select2-result-repository__watchers")
                            .append(e.watchers_count + " Watchers"),
                        t
                    );
                },
                templateSelection: function (e) {
                    return e.full_name || e.text;
                },
            });

            $("#datatable").DataTable();
            $(".dataTables_length select").addClass("form-select form-select-sm");

            toastr.options = {
                "closeButton": false,
                "debug": false,
                "newestOnTop": false,
                "progressBar": false,
                "positionClass": "toast-top-right",
                "preventDuplicates": false,
                "onclick": null,
                "showDuration": 300,
                "hideDuration": 1000,
                "timeOut": 5000,
                "extendedTimeOut": 1000,
                "showEasing": "swing",
                "hideEasing": "linear",
                "showMethod": "fadeIn",
                "hideMethod": "fadeOut"
            };

            toastr["success"]("Are you the six fingered man?");

            var previewTemplate,
                dropzone,
                dropzonePreviewNode = document.querySelector("#dropzone-preview-list");
                (
                    (dropzonePreviewNode.id = ""),
                    dropzonePreviewNode &&
                    (
                        (previewTemplate = dropzonePreviewNode.parentNode.innerHTML),
                        dropzonePreviewNode.parentNode.removeChild(dropzonePreviewNode),
                        (
                            dropzone = new Dropzone(".dropzone", {
                                url: "https://httpbin.org/post",
                                method: "post",
                                previewTemplate: previewTemplate,
                                previewsContainer: "#dropzone-preview",
                            })
                        )
                    )
                )
            ;
        
        });
    </script>
@endpush